int fd_mount; // Valid file descriptor
struct statfs fs_info;
int result;

// Get filesystem statistics for the descriptor
result = fstatfs64(fd_mount, &fs_info);

if (result == 0) {
    // Success
    long blk_size = fs_info.f_bsize;
    unsigned long free_blks = fs_info.f_bfree;
    long fs_type = fs_info.f_type;
} else {
    // Check errno for EBADF or EFAULT
    return -1;
}
